import unicodeCaseFold from "./column-label-casefold.json";

// Generated by scripts/gen_column_label_casefold.py from the server's Unicode 17
// data: browser casing tables differ, and upper/lower is not Python casefold.
const FOLDS: Readonly<Record<string, string>> = unicodeCaseFold;

/** The exact caseless key used by the server's column_keyed(). No normalization. */
export function columnLabelFold(value: string): string {
  return Array.from(value, (character) => FOLDS[character] ?? character).join("");
}
